function validate([allowed, words]) {
  if (typeof allowed !== 'string' || allowed.length < 1 || allowed.length > 26) return 'allowed needs 1 to 26 characters.';
  if (!/^[a-z]+$/.test(allowed)) return 'allowed may only use lowercase letters.';
  if (new Set(allowed).size !== allowed.length) return 'The characters of allowed must be distinct.';
  if (!Array.isArray(words) || words.length < 1 || words.length > 10000) return 'words needs 1 to 10^4 strings.';
  if (words.some(w => typeof w !== 'string' || w.length < 1 || w.length > 10)) return 'Each word has 1 to 10 characters.';
  if (words.some(w => !/^[a-z]+$/.test(w))) return 'Words may only use lowercase letters.';
  return null;
}

