function countConsistentStrings(allowed, words) {
  const permitted = new Set(allowed);
  let count = 0;

  for (const word of words) {
    let consistent = true;
    for (const char of word) {
      if (!permitted.has(char)) {
        consistent = false;
        break;
      }
    }
    if (consistent) {
      count++;
    }
  }
  return count;
}

