function countConsistentStrings(allowed, words) {
  // Search the allowed string for every character of every word.
  let total = 0;
  for (const word of words) {
    let ok = true;
    for (let i = 0; i < word.length; i++) if (allowed.indexOf(word[i]) === -1) ok = false;
    if (ok) total++;
  }
  return total;
}

