function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const alphabet = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abcde';
  // allowed is a random set of distinct letters from the alphabet.
  const letters = [...alphabet];
  for (let i = letters.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [letters[i], letters[j]] = [letters[j], letters[i]];
  }
  const allowed = letters.slice(0, 1 + pick(letters.length)).join('');
  const count = size === 'large' ? 1900 + pick(101) : 1 + pick(6);
  const longest = size === 'large' ? 10 : 4;
  const share = rand();
  const words = Array.from({ length: count }, () => {
    // Some words use allowed letters only; the rest draw from the whole alphabet.
    const source = rand() < share ? allowed : alphabet;
    return Array.from({ length: 1 + pick(longest) }, () => source[pick(source.length)]).join('');
  });
  return [allowed, words];
}
